import React, { useState } from 'react';
import { Star, Heart, Clock, Flame } from 'lucide-react';
import { useApp } from '../context/AppContext';
import { useNavigate } from 'react-router-dom';

/* ── Palette ── */
export const C = {
  bg:       '#111111',
  card:     '#1e1e1e',
  card2:    '#252525',
  border:   '#2a2a2a',
  orange:   '#FF6B35',
  orangeL:  '#FF8C5A',
  text:     '#ffffff',
  muted:    '#999999',
  muted2:   '#666666',
  input:    '#1e1e1e',
  inputB:   '#2e2e2e',
};

/* ── Orange Button ── */
export function BtnOrange({ children, onClick, style, disabled, outline }) {
  return (
    <button
      disabled={disabled}
      onClick={onClick}
      style={{
        width: '100%',
        padding: '14px',
        borderRadius: 12,
        fontWeight: 700,
        fontSize: 15,
        cursor: disabled ? 'not-allowed' : 'pointer',
        transition: 'opacity 0.2s',
        opacity: disabled ? 0.5 : 1,
        background: outline ? 'transparent' : C.orange,
        color: outline ? C.orange : '#fff',
        border: outline ? `1.5px solid ${C.orange}` : 'none',
        ...style,
      }}
    >
      {children}
    </button>
  );
}

/* ── Text Input ── */
export function TextInput({ icon: Icon, placeholder, value, onChange, type = 'text', rightIcon }) {
  return (
    <div style={{
      display: 'flex', alignItems: 'center', gap: 10,
      background: C.input, border: `1px solid ${C.inputB}`,
      borderRadius: 10, padding: '12px 14px',
    }}>
      {Icon && <Icon size={18} color={C.muted} />}
      <input
        type={type}
        placeholder={placeholder}
        value={value}
        onChange={onChange}
        style={{
          flex: 1, background: 'none', border: 'none', color: C.text,
          fontSize: 14, outline: 'none',
        }}
      />
      {rightIcon}
    </div>
  );
}

/* ── Rating Stars ── */
export function RatingBadge({ rating, reviews }) {
  return (
    <span style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 12, color: C.orange, fontWeight: 600 }}>
      <Star size={12} fill={C.orange} color={C.orange} />
      {rating}
      {reviews && <span style={{ color: C.muted, fontWeight: 400 }}>({reviews})</span>}
    </span>
  );
}

/* ── Tag Pill ── */
export function TagPill({ label, style }) {
  return (
    <span style={{
      padding: '3px 10px', borderRadius: 20,
      background: 'rgba(255,107,53,0.12)', color: C.orange,
      fontSize: 11, fontWeight: 600, whiteSpace: 'nowrap',
      ...style,
    }}>
      {label}
    </span>
  );
}

/* ── Food Card (horizontal list) ── */
export function FoodCardH({ food }) {
  const { favorites, toggleFavoriteFood } = useApp();
  const isFav = favorites.foods.includes(food.id);
  const navigate = useNavigate();

  return (
    <div
      onClick={() => navigate(`/food/${food.id}`)}
      style={{
        background: C.card, borderRadius: 14, overflow: 'hidden',
        width: 160, flexShrink: 0, cursor: 'pointer',
        border: `1px solid ${C.border}`,
      }}
    >
      <div style={{ position: 'relative' }}>
        <img src={food.image} alt={food.name} style={{ width: '100%', height: 110, objectFit: 'cover' }} />
        <button
          onClick={e => { e.stopPropagation(); toggleFavoriteFood(food.id); }}
          style={{
            position: 'absolute', top: 8, right: 8,
            background: 'rgba(0,0,0,0.5)', border: 'none', borderRadius: '50%',
            width: 28, height: 28, display: 'flex', alignItems: 'center', justifyContent: 'center',
            cursor: 'pointer',
          }}
        >
          <Heart size={14} fill={isFav ? '#ff4d6d' : 'transparent'} color={isFav ? '#ff4d6d' : '#fff'} />
        </button>
      </div>
      <div style={{ padding: '10px 10px 12px' }}>
        <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 2 }}>{food.name}</div>
        <div style={{ fontSize: 11, color: C.muted, marginBottom: 6 }}>
          <Flame size={10} style={{ marginRight: 2 }} />{food.calories} kcal
        </div>
        <RatingBadge rating={food.rating} />
      </div>
    </div>
  );
}

